INSERT INTO catalog_title (title_id,minimum_tier_id,title_name,maturity_rating,content_type,synopsis) VALUES
('9afdf956-9c75-d5d1-2f55-b20b44d54ba7',0,'Dick Johnson Is Dead','PG-13','Movie','As her father nears the end of his life, filmmaker Kirsten Johnson stages his death in inventive and comical ways to help them both face the inevitable.'),
('76285431-9e2a-0eaf-afd9-1d2b981c1cac',1,'My Little Pony: A New Generation','PG','Movie','Equestria\'s divided. But a bright-eyed hero believes Earth Ponies, Pegasi and Unicorns should be pals — and, hoof to heart, she’s determined to prove it.'),
('c961831e-7e65-7f2e-4ced-6a0c6e69afe2',2,'Sankofa','R','Movie','On a photo shoot in Ghana, an American model slips back in time, becomes enslaved on a plantation and bears witness to the agony of her ancestral past.'),
('914eb699-3335-7ac7-3370-04fcb568a4d7',3,'The Starling','PG-13','Movie','A woman adjusting to life after a loss contends with a feisty bird that\'s taken over her garden — and a husband who\'s struggling to find a way forward.'),
('ad980806-826b-25e8-669b-3b8cd2d95648',0,'Je Suis Karl','R','Movie','After most of her family is murdered in a terrorist bombing, a young woman is unknowingly lured into joining the very group that killed them.'),
